/**
 * Prebuild for functions: single-source prompt files + shared matching module.
 * - Embeds assets/prompts/exercise-record-rules.md and
 *   assets/image-style/gymiq-style-v3-prompt.md as TS string constants + sha256.
 * - Regenerates functions/src/shared/similarExercises.ts from
 *   src/domains/exercises/matching/similarExercises.ts (header + verbatim body).
 * Run automatically via functions build; never edit the generated files.
 */
const fs = require('fs')
const path = require('path')
const crypto = require('crypto')

const root = path.resolve(__dirname, '..')
const read = (p) => fs.readFileSync(path.join(root, p), 'utf-8')
const sha = (s) => crypto.createHash('sha256').update(s).digest('hex')

const rules = read('assets/prompts/exercise-record-rules.md')
const style = read('assets/image-style/gymiq-style-v3-prompt.md')

const gen = `// GENERATED by scripts/generate-function-prompts.cjs — DO NOT EDIT.
// Sources: assets/prompts/exercise-record-rules.md, assets/image-style/gymiq-style-v3-prompt.md
export const EXERCISE_RECORD_RULES_MD = ${JSON.stringify(rules)}
export const EXERCISE_RECORD_RULES_SHA256 = '${sha(rules)}'
export const STYLE_PROMPT_MD = ${JSON.stringify(style)}
export const STYLE_PROMPT_SHA256 = '${sha(style)}'
`
fs.mkdirSync(path.join(root, 'functions/src/generated'), { recursive: true })
fs.writeFileSync(path.join(root, 'functions/src/generated/promptSources.generated.ts'), gen)

const matching = read('src/domains/exercises/matching/similarExercises.ts')
const header = '// GENERATED copy of src/domains/exercises/matching/similarExercises.ts — DO NOT EDIT (see scripts/generate-function-prompts.cjs)\n'
fs.writeFileSync(path.join(root, 'functions/src/shared/similarExercises.ts'), header + matching)

console.log('generated: promptSources.generated.ts + shared/similarExercises.ts')
